<?php if ($hours): $names=array(1=>'Senin',2=>'Selasa',3=>'Rabu',4=>'Kamis',5=>'Jumat',6=>'Sabtu',7=>'Minggu'); ?><section class="shop-store-hours"><div class="shop-section-head"><div><span class="shop-eyebrow">INFORMASI TOKO</span><h2>Jam layanan</h2></div></div><dl><?php foreach($hours as $hour): ?><div><dt><?= $names[(int)$hour['day_of_week']] ?></dt><dd><?= $hour['is_closed']?'Libur':html_escape(substr($hour['opens_at'],0,5)).' – '.html_escape(substr($hour['closes_at'],0,5)) ?></dd></div><?php endforeach; ?></dl></section><?php endif; ?>
